-- Fictional local fixtures only; run after the merchant-fee fixture and Owner setup.
begin;
create function pg_temp.rec_snapshot() returns jsonb language plpgsql as $$
declare relation text; rows jsonb; snapshot jsonb:='{}';begin
 foreach relation in array array['bank_reconciliations','bank_reconciliation_requests','bank_reconciliation_revisions','journal_entries','journal_lines'] loop
  execute format('select coalesce(jsonb_agg(to_jsonb(r) order by to_jsonb(r)::text),''[]''::jsonb) from public.%I r',relation) into rows;
  snapshot:=snapshot||jsonb_build_object(relation,rows);
 end loop;
 return snapshot;
end$$;
create function pg_temp.rec_assert(ok boolean,message text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'Assertion: %',message;end if;end$$;
create function pg_temp.rec_reject(statement text,message text) returns void language plpgsql as $$declare rejected boolean:=false;begin begin execute statement;exception when others then if position(message in sqlerrm)>0 then rejected:=true;else raise;end if;end;if not rejected then raise exception 'Expected rejection: %',message;end if;end$$;
insert into coa_accounts(code,name,type,normal_balance,is_header) values('740010','Fictional bank fee','BEBAN','D',false),('810001','Fictional bank interest','PENDAPATAN','K',false) on conflict(code) do update set is_active=true,is_header=false;
create temp table rec_input as select jsonb_build_object('account_id','e6600000-0000-4000-8000-000000000002','tanggal',(now() at time zone 'Asia/Jakarta')::date,'saldo_bank',0,'biaya_adm',25.25,'bunga',3.10,'catatan','Fictional bank reconciliation') header,
 (select coalesce(sum(l.debit-l.credit),0) from journal_lines l join journal_entries e on e.id=l.entry_id join coa_accounts a on a.id=l.account_id where a.code='1112' and e.tanggal<=(now() at time zone 'Asia/Jakarta')::date) baseline;
update rec_input set header=jsonb_set(header,'{saldo_bank}',to_jsonb(baseline+3.10-25.25));
insert into journal_entries(id,no_jurnal,tanggal,deskripsi,source) values('efa10000-0000-4000-8000-000000000001','FUTURE.BANK.FIXTURE',(now() at time zone 'Asia/Jakarta')::date+1,'Fictional future transaction','fixture');
insert into journal_lines(entry_id,account_id,debit,credit) select 'efa10000-0000-4000-8000-000000000001',id,1000000,0 from coa_accounts where code='1112';
insert into journal_lines(entry_id,account_id,debit,credit) select 'efa10000-0000-4000-8000-000000000001',id,0,1000000 from coa_accounts where code='510001';
grant select on rec_input to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','e1100000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"role":"authenticated"}',true);
create temp table rec_result as select public.mutate_bank_reconciliation('rec-create','create',null,null,(select header from rec_input),null) value;
select pg_temp.rec_assert((select r.saldo_buku=i.baseline and r.selisih=0 and r.biaya_adm=25.25 and r.bunga=3.10 from bank_reconciliations r cross join rec_input i where r.id=(select(value->>'reconciliation_id')::uuid from rec_result)),'as-of-date snapshot excludes future entry and keeps cents');
select pg_temp.rec_assert(public.mutate_bank_reconciliation('rec-create','create',null,null,(select header from rec_input),null)=(select value from rec_result),'create retry');
select pg_temp.rec_assert(public.get_bank_reconciliation_result('rec-create')=(select value from rec_result),'read-only recovery');
select pg_temp.rec_reject($q$select public.mutate_bank_reconciliation('rec-create','create',null,null,jsonb_set((select header from rec_input),'{bunga}','99'),null)$q$,'rincian berbeda');
select pg_temp.rec_reject($q$select public.mutate_bank_reconciliation('rec-nan','create',null,null,jsonb_set((select header from rec_input),'{biaya_adm}','"NaN"'),null)$q$,'Nilai');
select pg_temp.rec_reject($q$select public.mutate_bank_reconciliation('rec-infinite','create',null,null,jsonb_set((select header from rec_input),'{tanggal}','"-infinity"'),null)$q$,'Tanggal');
select pg_temp.rec_reject($q$select public.mutate_bank_reconciliation('rec-future','create',null,null,jsonb_set((select header from rec_input),'{tanggal}',to_jsonb((now() at time zone 'Asia/Jakarta')::date+1)),null)$q$,'Tanggal');
select pg_temp.rec_reject($q$insert into public.bank_reconciliations(tanggal) values(current_date)$q$,'permission denied');
select pg_temp.rec_reject($q$insert into public.journal_entries(no_jurnal,tanggal,deskripsi,source) values('FORGED.BANK.REC',current_date,'Forged','bank-rec')$q$,'jalur resmi');
create temp table rec_original as select e.id,to_jsonb(e) header,(select jsonb_agg(to_jsonb(l) order by id) from journal_lines l where l.entry_id=e.id) lines from journal_entries e join bank_reconciliations r on r.journal_entry_id=e.id where r.id=(select(value->>'reconciliation_id')::uuid from rec_result);
reset role;
create function public.rec_fault() returns trigger language plpgsql as $$begin raise exception 'REC_FINAL_FAULT';end$$;
create trigger rec_fault before insert on public.bank_reconciliation_requests for each row execute function public.rec_fault();
create temp table rec_before as select pg_temp.rec_snapshot() snapshot;
set local role authenticated;
select pg_temp.rec_reject($q$select public.mutate_bank_reconciliation('rec-fault','edit',(select(value->>'reconciliation_id')::uuid from rec_result),0,jsonb_set((select header from rec_input),'{biaya_adm}','30'),'Correct fee')$q$,'REC_FINAL_FAULT');
reset role;
select pg_temp.rec_assert((select snapshot=pg_temp.rec_snapshot() from rec_before),'final failure rolls back header, reversal, replacement, audit and request');
drop trigger rec_fault on public.bank_reconciliation_requests;drop function public.rec_fault();
update accounting_locks set closed_until=(now() at time zone 'Asia/Jakarta')::date;
set local role authenticated;
select pg_temp.rec_reject($q$select public.mutate_bank_reconciliation('rec-closed','void',(select(value->>'reconciliation_id')::uuid from rec_result),0,'{}','Void closed')$q$,'ditutup');
reset role;update accounting_locks set closed_until=null;
set local role authenticated;
select public.mutate_bank_reconciliation('rec-edit','edit',(select(value->>'reconciliation_id')::uuid from rec_result),0,jsonb_set(jsonb_set((select header from rec_input),'{biaya_adm}','50'),'{bunga}','10'),'Correct fee and interest');
select pg_temp.rec_assert((select r.saldo_buku=i.baseline and r.revision=1 and r.biaya_adm=50 and r.bunga=10 from bank_reconciliations r cross join rec_input i where r.id=(select(value->>'reconciliation_id')::uuid from rec_result)),'edit reverses original before taking a new snapshot');
select pg_temp.rec_assert((select o.header=to_jsonb(e) and o.lines=(select jsonb_agg(to_jsonb(l) order by id) from journal_lines l where l.entry_id=e.id) from rec_original o join journal_entries e on e.id=o.id),'original journal and lines retained exactly');
select pg_temp.rec_reject($q$select public.mutate_bank_reconciliation('rec-stale','void',(select(value->>'reconciliation_id')::uuid from rec_result),0,'{}','Old revision')$q$,'sudah berubah');
select public.mutate_bank_reconciliation('rec-void','void',(select(value->>'reconciliation_id')::uuid from rec_result),1,'{}','Cancel corrected reconciliation');
select public.mutate_bank_reconciliation('rec-void','void',(select(value->>'reconciliation_id')::uuid from rec_result),1,'{}','Cancel corrected reconciliation');
select pg_temp.rec_assert((select count(*)=2 from bank_reconciliation_revisions where reconciliation_id=(select(value->>'reconciliation_id')::uuid from rec_result)),'edit and void audit once');
select pg_temp.rec_assert((select coalesce(sum(l.debit-l.credit),0)=(select baseline from rec_input) from journal_lines l join journal_entries e on e.id=l.entry_id join coa_accounts a on a.id=l.account_id where a.code='1112' and e.tanggal<=(now() at time zone 'Asia/Jakarta')::date),'void restores full original bank balance');
reset role;
update cash_accounts set branch_id='e2200000-0000-4000-8000-000000000002' where id='e6600000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.headers','{"x-kamo-operational-branch":"e2200000-0000-4000-8000-000000000001"}',true);
select pg_temp.rec_reject($q$select public.mutate_bank_reconciliation('rec-create','create',null,null,(select header from rec_input),null)$q$,'Rekening hasil');
select pg_temp.rec_reject($q$select public.get_bank_reconciliation_result('rec-create')$q$,'Rekening hasil');
select pg_temp.rec_reject($q$select public.mutate_bank_reconciliation('rec-cross','create',null,null,(select header from rec_input),null)$q$,'Cabang rekening');
reset role;
select set_config('request.headers','{}',true);
update cash_accounts set branch_id=null where id='e6600000-0000-4000-8000-000000000002';
set local role authenticated;
create temp table rec_zero as select public.mutate_bank_reconciliation('rec-zero','create',null,null,jsonb_set(jsonb_set((select header from rec_input),'{biaya_adm}','0'),'{bunga}','0'),null) value;
select pg_temp.rec_assert((select journal_entry_id is null from bank_reconciliations where id=(select(value->>'reconciliation_id')::uuid from rec_zero)),'no adjustment does not create an empty journal');
select public.mutate_bank_reconciliation('rec-zero-void','void',(select(value->>'reconciliation_id')::uuid from rec_zero),0,'{}','Cancel snapshot without charges');
-- Later reconciliations prevent older snapshots being revised out of order.
create temp table rec_older as select public.mutate_bank_reconciliation('rec-older','create',null,null,(select header from rec_input),null) value;
create temp table rec_later as select public.mutate_bank_reconciliation('rec-later','create',null,null,(select header from rec_input),null) value;
select pg_temp.rec_reject($q$select public.mutate_bank_reconciliation('rec-old-block','void',(select(value->>'reconciliation_id')::uuid from rec_older),0,'{}','Cancel out of order')$q$,'lebih baru');
select public.mutate_bank_reconciliation('rec-later-void','void',(select(value->>'reconciliation_id')::uuid from rec_later),0,'{}','Cancel latest first');
select public.mutate_bank_reconciliation('rec-older-void','void',(select(value->>'reconciliation_id')::uuid from rec_older),0,'{}','Cancel prior next');
reset role;
insert into bank_reconciliations(id,tanggal) values('efa20000-0000-4000-8000-000000000002',(now() at time zone 'Asia/Jakarta')::date);
set local role authenticated;
select pg_temp.rec_assert(exists(select 1 from bank_reconciliations where id='efa20000-0000-4000-8000-000000000002'),'legacy unlinked history remains visible');
select pg_temp.rec_reject($q$select public.mutate_bank_reconciliation('rec-unlinked','void','efa20000-0000-4000-8000-000000000002',0,'{}','Cancel unlinked')$q$,'belum tertaut');
reset role;
insert into bank_reconciliations(id,tanggal,cash_account_id) values('efa20000-0000-4000-8000-000000000003','-infinity','e6600000-0000-4000-8000-000000000002');
set local role authenticated;
select pg_temp.rec_reject($q$select public.mutate_bank_reconciliation('rec-infinite-source','void','efa20000-0000-4000-8000-000000000003',0,'{}','Cancel nonfinite source')$q$,'Tanggal sumber');
reset role;
-- Legacy records with unattributed fees never guess a journal link.
insert into bank_reconciliations(id,tanggal,cash_account_id,biaya_adm) values('efa20000-0000-4000-8000-000000000001',(now() at time zone 'Asia/Jakarta')::date,'e6600000-0000-4000-8000-000000000002',25);
set local role authenticated;
select pg_temp.rec_reject($q$select public.mutate_bank_reconciliation('rec-legacy','void','efa20000-0000-4000-8000-000000000001',0,'{}','Cancel legacy')$q$,'hubungan jurnal');
reset role;
alter table profiles disable trigger guard_profile_privileges;
update profiles set role='FINANCE' where id='e1100000-0000-4000-8000-000000000002';
alter table profiles enable trigger guard_profile_privileges;
set local role authenticated;
select set_config('request.jwt.claim.sub','e1100000-0000-4000-8000-000000000002',true);
select public.mutate_bank_reconciliation('rec-finance','create',null,null,(select header from rec_input),null);
select pg_temp.rec_reject($q$select public.mutate_bank_reconciliation('rec-finance-void','void',(select(value->>'reconciliation_id')::uuid from rec_older),0,'{}','Finance cannot void')$q$,'Hanya Owner');
reset role;
insert into role_capabilities(role,all_branches,create_accounts) values('FINANCE',false,false) on conflict(role) do update set all_branches=false;
set local role authenticated;
select pg_temp.rec_reject($q$select public.mutate_bank_reconciliation('rec-partial','create',null,null,(select header from rec_input),null)$q$,'seluruh cabang');
select pg_temp.rec_assert((select count(*)=0 from bank_reconciliations),'partial role cannot read global reconciliation');
reset role;
update role_capabilities set all_branches=true where role='FINANCE';
insert into role_modules(role,module_id) values('FINANCE','dashboard');
set local role authenticated;
select pg_temp.rec_reject($q$select public.mutate_bank_reconciliation('rec-module','create',null,null,(select header from rec_input),null)$q$,'Kas & Bank');
reset role;
select set_config('request.jwt.claim.sub','e1100000-0000-4000-8000-000000000001',true);
alter table profiles disable trigger guard_profile_privileges;
update profiles set is_active=false where id='e1100000-0000-4000-8000-000000000001';
alter table profiles enable trigger guard_profile_privileges;
set local role authenticated;
select pg_temp.rec_reject($q$select public.get_bank_reconciliation_result('rec-create')$q$,'Akses keuangan');
rollback;
